#!/usr/bin/env python3
"""Direct fix for all 'Autogenerated wrapper for' docstrings."""

import re
from pathlib import Path

total = 0
for py_file in Path("src/britecore_sdk/api/api_calls").rglob("*.py"):
    if "__init__" in py_file.name:
        continue

    content = py_file.read_text(encoding="utf-8")
    original_len = len(content)

    # Simple replacement: "Autogenerated wrapper for ``/path``" becomes a proper docstring
    # Pattern: """Autogenerated wrapper for ``/path/to/endpoint``."""
    pattern = r'"""Autogenerated wrapper for ``([^`]+)``\."""'

    def make_docstring(match):
        path = match.group(1)
        endpoint = path.split("/")[-1]
        words = endpoint.replace("_", " ").title()
        return f'''"""{words}.

    Send a request to {path}. Returns processed result from
    ``process_result(...)`` and accepts ``RequestParameters`` overrides.

    Args:
        **kwargs: Additional request parameters (timeout, retry, headers, dry_run, etc.).

    Returns:
        Any: The processed response containing the requested data.

    Raises:
        BritecoreError: Various exceptions from process_result if the API returns an error.
    """'''

    new_content = re.sub(pattern, make_docstring, content)

    if new_content != content:
        count = len(re.findall(pattern, content))
        py_file.write_text(new_content, encoding="utf-8")
        print(f"{py_file.name}: {count} fixed")
        total += count

print(f"\nTOTAL FIXED: {total}")
